import type { Relationship, Relationships } from '@servicenow/sdk-build-core'
import type { Project } from '../../project'

type Via =
    | {
          type: 'string'
          value: string
      }
    | {
          type: 'object'
          value: Record<string, string>
      }
    | {
          type: 'regex'
          value: { parent: [string, string]; child: [string, string] }[]
      }
    | {
          type: 'function'
          value: string
      }
    | {
          type: 'unknown'
          value: unknown
      }

/**
 * Describes how a parent and descendant table relate to each other.
 */
type DescendantDescriptor = {
    inverse: boolean
    via: Via
    descendantTable: string
    composite: boolean
}

/**
 * Represents a descendant relationship in the hierarchy tree with metadata.
 * Includes node identification, relationship type, and potential cyclic references.
 */
type DescendantRelationship = {
    nodeId: string
    table: string
    via: Via
    inverse: boolean
    composite: boolean
    cycleTargetNodeId?: string
    cyclicReferences?: string[]
    relationships?: DescendantRelationships
}

/**
 * A map of descendant table names to their relationship metadata.
 */
type DescendantRelationships = {
    [descendantTable: string]: DescendantRelationship
}

/**
 * Represents the complete relationship hierarchy for a given table.
 * @template T - The table name type
 */
export type RelationshipHierarchy<T extends string> = Record<
    T,
    {
        nodeId: string
        table: T
        composite: boolean
        cyclicReferences?: string[]
        relationships?: DescendantRelationships
    }
>

/**
 * Resolves and manages table relationships spread across plugins.
 * Builds hierarchical relationship trees, detects cycles, and identifies root tables.
 */
export class RelationshipResolver {
    private readonly descendantParents: Map<string, Set<string>> = new Map()
    private readonly parentDescendantRelations: Map<string, Map<string, DescendantDescriptor>> = new Map()
    private nodeIdCounter = 0
    /**
     * Creates a new RelationshipResolver instance.
     * @param project - The project containing the table relationships to resolve
     */
    constructor(private readonly project: Project) {
        this.init()
    }

    /**
     * Generates a unique node identifier for the relationship tree.
     * @returns A unique node ID string
     */
    private generateNodeId(): string {
        return `node${++this.nodeIdCounter}`
    }

    /**
     * Initializes the resolver by processing all relationships from project plugins.
     * Populates internal maps tracking parent-descendant relationships.
     */
    private init(): void {
        const plugins = this.project.getPlugins().toArray()
        for (const plugin of plugins) {
            const searchableRelationships = plugin.getRelationships()
            for (const [parent, relationships] of Object.entries(searchableRelationships)) {
                this.processRelationship(parent, relationships)
            }
        }
    }

    /**
     * Normalizes the 'via' field of a relationship into a consistent format.
     * @param via - The relationship via field (string, object, function, or regex)
     * @returns A normalized Via object with type and value
     */
    private normalizeVia(via: Relationship['via']): Via {
        if (typeof via === 'string') {
            return { type: 'string', value: via }
        } else if (Array.isArray(via)) {
            return { type: 'regex', value: via }
        } else if (typeof via === 'object') {
            return { type: 'object', value: via }
        } else if (typeof via === 'function') {
            return { type: 'function', value: via.toString() }
        } else {
            return { type: 'unknown', value: via }
        }
    }

    private isComposite(table: string): boolean {
        return this.project.getPlugins().isComposite(table)
    }

    /**
     * Recursively processes relationships for a parent table.
     * Updates internal maps tracking descendant-parent relationships.
     * @param parent - The parent table name
     * @param relationships - The relationships configuration for the parent table
     */
    private processRelationship(parent: string, relationships: Relationships | undefined): void {
        if (!relationships) {
            return
        }

        const parents = this.descendantParents.get(parent) ?? new Set()
        this.descendantParents.set(parent, parents)

        for (const [descendant, relationship] of Object.entries(relationships)) {
            const parents = this.descendantParents.get(descendant) ?? new Set()
            this.descendantParents.set(descendant, parents)
            const isDescendant = relationship.descendant

            if (isDescendant) {
                parents.add(parent)
                this.descendantParents.set(descendant, parents)

                const relations = this.parentDescendantRelations.get(parent) ?? new Map()
                relations.set(descendant, {
                    descendantTable: descendant,
                    via: this.normalizeVia(relationship.via),
                    inverse: relationship.inverse ?? false,
                    composite: this.isComposite(descendant),
                })
                this.parentDescendantRelations.set(parent, relations)
            }

            this.processRelationship(descendant, relationship.relationships)
        }
    }

    /**
     * Finds all root tables (tables with no parents) for a given table.
     * Uses depth-first search with cycle detection.
     * @param table - The table to find roots for
     * @param visited - Set of already visited tables to prevent infinite loops
     * @returns Set of root table names
     */
    private findAllRoots(table: string, visited: Set<string> = new Set()): Set<string> {
        if (visited.has(table)) {
            return new Set()
        }
        if (this.isRoot(table)) {
            return new Set([table])
        }
        visited.add(table)
        const allRoots: Set<string> = new Set()
        // biome-ignore lint/style/noNonNullAssertion: we ensure its persent in isRoot
        const parents = this.descendantParents.get(table)!
        for (const parent of parents) {
            this.findAllRoots(parent, visited).forEach((root) => allRoots.add(root))
        }
        return allRoots
    }

    /**
     * Adds cyclic reference metadata to the relationship tree.
     * @param relationships - The relationship tree to annotate
     * @param cyclicRefs - Map of node IDs to their cyclic reference node IDs
     */
    private addCyclicReferencesToTree(
        relationships: DescendantRelationships | undefined,
        cyclicRefs: Map<string, string[]>
    ): void {
        if (!relationships) {
            return
        }
        for (const [, relationship] of Object.entries(relationships)) {
            const refs = cyclicRefs.get(relationship.nodeId)
            if (refs) {
                relationship.cyclicReferences = refs
            }
            this.addCyclicReferencesToTree(relationship.relationships, cyclicRefs)
        }
    }

    /**
     * Recursively builds the relationship tree for a table.
     * Detects and marks cyclic relationships during traversal.
     * @param table - The table to build relationships for
     * @param visitedPath - Map of visited tables to their node IDs in current path
     * @param cyclicRefs - Map collecting cyclic references by node ID
     * @returns The descendant relationships tree, or undefined if no relationships exist
     */
    private buildRelationship(
        table: string,
        visitedPath: Map<string, string> = new Map(),
        cyclicRefs: Map<string, string[]> = new Map()
    ): DescendantRelationships | undefined {
        const relations = this.parentDescendantRelations.get(table)?.values()
        if (!relations) {
            return undefined
        }
        const relationship: DescendantRelationships = {}
        for (const relation of relations) {
            const nodeId = this.generateNodeId()
            const cycleTargetNodeId = visitedPath.get(relation.descendantTable)
            const isCycle = cycleTargetNodeId !== undefined

            if (isCycle) {
                const refs = cyclicRefs.get(cycleTargetNodeId) ?? []
                refs.push(nodeId)
                cyclicRefs.set(cycleTargetNodeId, refs)
                relationship[relation.descendantTable] = {
                    nodeId,
                    table: relation.descendantTable,
                    via: relation.via,
                    inverse: relation.inverse,
                    composite: relation.composite,
                    cycleTargetNodeId,
                }
            } else {
                visitedPath.set(relation.descendantTable, nodeId)
                const associatedRelations = this.buildRelationship(relation.descendantTable, visitedPath, cyclicRefs)
                visitedPath.delete(relation.descendantTable)
                relationship[relation.descendantTable] = {
                    nodeId,
                    table: relation.descendantTable,
                    via: relation.via,
                    inverse: relation.inverse,
                    composite: relation.composite,
                    ...(associatedRelations && { relationships: associatedRelations }),
                }
            }
        }
        return relationship
    }

    /**
     * Generates the complete relationship hierarchy for a given table.
     * @template T - The table name type
     * @param table - The root table to generate hierarchy for
     * @returns The complete relationship hierarchy including cyclic references
     */
    private generateRelationshipHierarchy<T extends string>(table: T): RelationshipHierarchy<T> {
        const rootNodeId = this.generateNodeId()
        const visitedPath = new Map<string, string>([[table, rootNodeId]])
        const cyclicRefs = new Map<string, string[]>()
        const relationships = this.buildRelationship(table, visitedPath, cyclicRefs)
        this.addCyclicReferencesToTree(relationships, cyclicRefs)
        const rootCyclicRefs = cyclicRefs.get(rootNodeId)
        return {
            [table]: {
                nodeId: rootNodeId,
                table,
                composite: this.isComposite(table),
                ...(rootCyclicRefs && { cyclicReferences: rootCyclicRefs }),
                ...(relationships && { relationships }),
            },
        } as RelationshipHierarchy<T>
    }

    /**
     * Checks if a table is a root table (has no parent tables).
     * Assumption: Root table doesn't have any parent table even via cylic references.
     * @param table - The table name to check
     * @returns True if the table is a root, false otherwise
     */
    private isRoot(table: string): boolean {
        return !this.descendantParents.has(table) || this.descendantParents.get(table)?.size === 0
    }

    /**
     * Validates that all 'via' fields in the hierarchy are supported types.
     * Currently rejects hierarchies containing function-based relationships.
     * @param hierarchy - The relationship hierarchy to validate
     * @returns True if all via fields are supported, false otherwise
     */
    private validateViaInHierarchy(hierarchy: DescendantRelationships | undefined): boolean {
        if (!hierarchy) {
            return true
        }
        for (const [, relationship] of Object.entries(hierarchy)) {
            if (relationship.via.type === 'function' || relationship.via.type === 'unknown') {
                return false
            }
            if (relationship.relationships) {
                if (!this.validateViaInHierarchy(relationship.relationships)) {
                    return false
                }
            }
        }
        return true
    }

    /**
     * Resolves all possible relationship hierarchies for a given table.
     * Finds all root tables and generates hierarchies from each root.
     * Filters out hierarchies with unsupported relationship types.
     * @param table - The table to resolve relationships for
     * @returns Array of all valid relationship hierarchies
     */
    public resolveRelationship(table: string): RelationshipHierarchy<string>[] {
        const roots = this.findAllRoots(table)
        const allPossibleHierarchies: RelationshipHierarchy<string>[] = []
        for (const root of roots) {
            const hierarchy = this.generateRelationshipHierarchy(root)
            if (!hierarchy) {
                continue
            }
            if (!this.validateViaInHierarchy(hierarchy[root]?.relationships)) {
                continue // skip unsupported hierarchies
            }
            allPossibleHierarchies.push(hierarchy)
        }
        return allPossibleHierarchies
    }
}
